const clean=(v,n=12000)=>String(v??'').trim().slice(0,n);
const bool=v=>v===true||v===1||v==='1'||v==='true'||v==='on';
const parse=(v,f)=>{try{return typeof v==='string'?JSON.parse(v||''):(v??f);}catch{return f;}};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EMAIL_RE=/^[^\s@]+@[^\s@]+\.[A-Za-z]{2,}$/;
let ready=false;

export async function ensureEmailAutomationSchema(env){
  if(ready||!env?.DB)return;
  const statements=[
    `CREATE TABLE IF NOT EXISTS email_automation_flows (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'custom',status TEXT NOT NULL DEFAULT 'draft',trigger_type TEXT NOT NULL DEFAULT 'lead_created',trigger_config_json TEXT NOT NULL DEFAULT '{}',allow_reentry INTEGER NOT NULL DEFAULT 0,definition_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`,
    `CREATE TABLE IF NOT EXISTS email_automation_versions (id INTEGER PRIMARY KEY AUTOINCREMENT,flow_id INTEGER NOT NULL,version_no INTEGER NOT NULL,snapshot_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(flow_id,version_no),FOREIGN KEY(flow_id) REFERENCES email_automation_flows(id) ON DELETE CASCADE)`,
    `CREATE TABLE IF NOT EXISTS email_automation_enrollments (id INTEGER PRIMARY KEY AUTOINCREMENT,flow_id INTEGER NOT NULL,lead_id INTEGER NOT NULL,entry_key TEXT NOT NULL DEFAULT 'initial',context_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'active',current_step_index INTEGER NOT NULL DEFAULT 0,next_run_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_error TEXT NOT NULL DEFAULT '',entered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(flow_id,lead_id,entry_key),FOREIGN KEY(flow_id) REFERENCES email_automation_flows(id) ON DELETE CASCADE,FOREIGN KEY(lead_id) REFERENCES contact_leads(id) ON DELETE CASCADE)`,
    `CREATE TABLE IF NOT EXISTS email_automation_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,enrollment_id INTEGER NOT NULL,flow_id INTEGER NOT NULL,lead_id INTEGER NOT NULL,step_id TEXT NOT NULL DEFAULT '',step_type TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT '',provider_id TEXT NOT NULL DEFAULT '',open_token TEXT NOT NULL DEFAULT '',opened_at TEXT NOT NULL DEFAULT '',open_count INTEGER NOT NULL DEFAULT 0,error_text TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(enrollment_id,step_id),FOREIGN KEY(enrollment_id) REFERENCES email_automation_enrollments(id) ON DELETE CASCADE)`,
    `CREATE TABLE IF NOT EXISTS email_automation_suppressions (email TEXT PRIMARY KEY,reason TEXT NOT NULL DEFAULT 'unsubscribed',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`,
    `CREATE TABLE IF NOT EXISTS email_automation_groups (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`,
    `CREATE TABLE IF NOT EXISTS email_automation_group_members (group_id INTEGER NOT NULL,lead_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(group_id,lead_id),FOREIGN KEY(group_id) REFERENCES email_automation_groups(id) ON DELETE CASCADE,FOREIGN KEY(lead_id) REFERENCES contact_leads(id) ON DELETE CASCADE)`,
    `CREATE TABLE IF NOT EXISTS email_automation_state (state_key TEXT PRIMARY KEY,state_value TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`,
    `CREATE INDEX IF NOT EXISTS idx_email_automation_due ON email_automation_enrollments(status,next_run_at,id)`,
    `CREATE INDEX IF NOT EXISTS idx_email_automation_flow_status ON email_automation_flows(status,trigger_type,id)`,
    `CREATE INDEX IF NOT EXISTS idx_email_automation_runs_token ON email_automation_runs(open_token)`,
    `CREATE INDEX IF NOT EXISTS idx_email_automation_runs_flow ON email_automation_runs(flow_id,created_at)`,
    `CREATE INDEX IF NOT EXISTS idx_email_automation_group_lead ON email_automation_group_members(lead_id,group_id)`
  ];
  for(const sql of statements)await env.DB.prepare(sql).run().catch(()=>{});
  await env.DB.prepare("ALTER TABLE email_automation_enrollments ADD COLUMN context_json TEXT NOT NULL DEFAULT '{}'").run().catch(()=>{});
  ready=true;
}

const uid=(p='step')=>`${p}_${crypto.randomUUID()}`;
function defaultDesign(){return {primaryColor:'',secondaryColor:'',headingColor:'#2b151d',textColor:'#503943',borderColor:'#ead3bd',backgroundColor:'#f7f1ea',contentBackground:'#fffaf4',buttonRadius:999,fontFamily:'Arial, Helvetica, sans-serif'};}
function emailStep(name='Welcome email',subject='Welcome to @BrandName'){return {id:uid('email'),type:'email',name,config:{subject,preheader:'',senderName:'@BrandName',senderEmail:'',useDifferentReplyTo:false,replyTo:'',trackOpens:true,utmEnabled:true,utmSource:'email',utmMedium:'automation',utmCampaign:'lead-follow-up',language:'en',plainText:'Hi @FirstName,\n\nThank you for your interest in @BrandName.\n\nView this email online: @ViewInBrowser\n\nNot interested anymore? @Unsubscribe',design:defaultDesign(),blocks:[{id:uid('heading'),type:'heading',text:'Welcome to @BrandName, @FirstName!'},{id:uid('text'),type:'text',text:'Thank you for your interest. We are delighted to have you with us.'},{id:uid('button'),type:'button',text:'Get Started',url:'@WebsiteUrl'},{id:uid('footer'),type:'footer',text:'You are receiving this email because you contacted @BrandName. You may unsubscribe at any time.'}]}};}
function preparedEmail(name,subject,heading,message,buttonText='',buttonUrl='@WebsiteUrl',extras=[]){const s=emailStep(name,subject),blocks=[{id:uid('heading'),type:'heading',text:heading},{id:uid('text'),type:'text',text:message},...extras.map(x=>({id:uid(x.type||'text'),...x}))];if(buttonText)blocks.push({id:uid('button'),type:'button',text:buttonText,url:buttonUrl});blocks.push({id:uid('footer'),type:'footer',text:'You are receiving this email because you have an account, enquiry, purchase or subscription with @BrandName. You may unsubscribe at any time.'});s.config.blocks=blocks;s.config.preheader=message.replace(/@[A-Za-z0-9_]+/g,'').trim().slice(0,140);s.config.plainText=`Hi @FirstName,\n\n${message}\n\n${buttonText?`${buttonText}: ${buttonUrl}\n\n`:''}Not interested anymore? @Unsubscribe`;return s;}
const delay=(amount=1,unit='days',name='Wait')=>({id:uid('delay'),type:'delay',name,config:{amount,unit,offsetUnit:'hours',eventDirection:'after_end',atTime:'',weekday:'monday',monthDay:1,month:1,field:'date_of_birth'}});
const condition=(field='email',operator='is_not_empty',value='',name='Check condition')=>({id:uid('condition'),type:'condition',name,config:{match:'all',rules:[{field,operator,value}],trueAction:'continue',trueNextStepId:'',falseAction:'stop',falseNextStepId:''}});
const notification=(name='Internal notification')=>({id:uid('notification'),type:'notification',name,config:{email:'',subject:'Automation activity: @FlowName',message:'@ClientName reached @StepName in @FlowName.'}});
const groupAction=(mode='add_group',name='Update group')=>({id:uid(mode),type:mode,name,config:{groupId:0,groupName:''}});
const exitAction=(name='Exit workflow')=>({id:uid('exit'),type:'exit',name,config:{}});

