function sanitizeBlock(b={},i=0){const allowed=['navigation','hero','heading','text','button','image','divider','spacer','columns','special','product','gallery','blog_rss','social','footer'];const type=allowed.includes(clean(b.type,30))?clean(b.type,30):'text';return {id:clean(b.id||uid(type),100),type,text:clean(b.text,12000),url:clean(b.url,3000),imageUrl:clean(b.imageUrl||b.image_url,3000),alt:clean(b.alt,500),items:Array.isArray(b.items)?b.items.slice(0,12).map(x=>({text:clean(x?.text,300),url:clean(x?.url,3000),imageUrl:clean(x?.imageUrl,3000)})):[]};}
function sanitizeStep(s={},i=0){const allowed=['email','delay','condition','notification','add_group','remove_group','webhook','exit'];const type=allowed.includes(clean(s.type,30))?clean(s.type,30):'email',config={...(s.config||{})};if(type==='email'){config.subject=clean(config.subject,300);config.preheader=clean(config.preheader,300);config.senderName=clean(config.senderName,160);config.senderEmail=clean(config.senderEmail,240);config.replyTo=clean(config.replyTo,240);config.useDifferentReplyTo=bool(config.useDifferentReplyTo);config.trackOpens=config.trackOpens!==false;config.utmEnabled=config.utmEnabled!==false;config.utmSource=clean(config.utmSource,100)||'email';config.utmMedium=clean(config.utmMedium,100)||'automation';config.utmCampaign=clean(config.utmCampaign,160)||'lead-follow-up';config.language=clean(config.language,20)||'en';config.plainText=clean(config.plainText,50000);config.design={...defaultDesign(),...(config.design||{})};config.blocks=(Array.isArray(config.blocks)?config.blocks:[]).slice(0,80).map(sanitizeBlock);}if(type==='delay'){config.amount=Math.max(0,Math.min(3650,Number(config.amount||0)));config.unit=clean(config.unit,40)||'days';config.offsetUnit=['minutes','hours','days'].includes(config.offsetUnit)?config.offsetUnit:'hours';config.eventDirection=['before_start','after_end'].includes(config.eventDirection)?config.eventDirection:'after_end';config.atTime=clean(config.atTime,20);config.weekday=clean(config.weekday,20);config.monthDay=Math.max(1,Math.min(31,Number(config.monthDay||1)));config.month=Math.max(1,Math.min(12,Number(config.month||1)));config.field=clean(config.field,80);}if(type==='condition'){config.match=config.match==='any'?'any':'all';config.rules=(Array.isArray(config.rules)?config.rules:[]).slice(0,20).map(r=>({field:clean(r.field,80),operator:clean(r.operator,40),value:clean(r.value,1000)}));config.trueAction=['continue','stop','jump'].includes(config.trueAction)?config.trueAction:'continue';config.trueNextStepId=clean(config.trueNextStepId,100);config.falseAction=['continue','stop','jump'].includes(config.falseAction)?config.falseAction:'stop';config.falseNextStepId=clean(config.falseNextStepId,100);}if(type==='notification'){config.email=clean(config.email,240);config.subject=clean(config.subject,300);config.message=clean(config.message,5000);}if(type==='add_group'||type==='remove_group'){config.groupId=Math.max(0,Number(config.groupId||0));config.groupName=clean(config.groupName,160);}return {id:clean(s.id||uid(type),100),type,name:clean(s.name,160)||type.replace(/_/g,' '),config};}
function sanitizeDefinition(d={}){return {version:1,steps:(Array.isArray(d.steps)?d.steps:[]).slice(0,100).map(sanitizeStep),settings:{allowReentry:bool(d.settings?.allowReentry),timezone:clean(d.settings?.timezone,80)||'Asia/Kolkata'}};}
function rowFlow(r){return {...r,allowReentry:!!Number(r.allow_reentry),triggerConfig:parse(r.trigger_config_json,{}),definition:sanitizeDefinition(parse(r.definition_json,{}))};}
function validateFlow(f){const errors=[],steps=f.definition.steps||[];if(!clean(f.name,160))errors.push('Enter an automation name.');if(!steps.length)errors.push('Add at least one workflow step.');if(!steps.some(x=>x.type==='email'))errors.push('Add at least one email step.');for(const [i,s] of steps.entries()){if(s.type==='email'){if(!s.config.subject)errors.push(`Email ${i+1}: enter a subject.`);if(!s.config.blocks.length&&!s.config.plainText)errors.push(`Email ${i+1}: add email content.`);for(const b of s.config.blocks)if(b.type==='button'&&!b.url)errors.push(`Email ${i+1}: add the missing button URL for “${b.text||'Button'}”.`);}if(s.type==='condition')for(const [action,target,label] of [[s.config.trueAction,s.config.trueNextStepId,'matching'],[s.config.falseAction,s.config.falseNextStepId,'non-matching']])if(action==='jump'&&!steps.some((candidate,index)=>index>i&&candidate.id===target))errors.push(`Condition ${i+1}: choose a later destination for the ${label} branch.`);}return errors;}

export async function listEmailAutomations(env){await ensureEmailAutomationSchema(env);const r=await env.DB.prepare(`SELECT f.*,(SELECT COUNT(*) FROM email_automation_enrollments e WHERE e.flow_id=f.id AND e.status='active') active_contacts,(SELECT COUNT(*) FROM email_automation_runs x WHERE x.flow_id=f.id AND x.status='sent') sent_count,(SELECT COUNT(*) FROM email_automation_runs x WHERE x.flow_id=f.id AND x.open_count>0) opened_count FROM email_automation_flows f ORDER BY CASE f.status WHEN 'active' THEN 0 WHEN 'draft' THEN 1 ELSE 2 END,f.updated_at DESC,f.id DESC`).all();return (r.results||[]).map(rowFlow);}
export async function getEmailAutomation(env,id){await ensureEmailAutomationSchema(env);const row=await env.DB.prepare('SELECT * FROM email_automation_flows WHERE id=?').bind(Number(id)).first();if(!row)throw new Error('Email automation was not found.');const versions=(await env.DB.prepare('SELECT id,version_no,created_at FROM email_automation_versions WHERE flow_id=? ORDER BY version_no DESC LIMIT 30').bind(Number(id)).all()).results||[];return {...rowFlow(row),versions};}
export async function saveEmailAutomation(env,input={}){await ensureEmailAutomationSchema(env);const definition=sanitizeDefinition(input.definition||{}),status=['active','draft','paused'].includes(input.status)?input.status:'draft',flow={name:clean(input.name,160),category:clean(input.category,60)||'custom',status,triggerType:clean(input.triggerType||input.trigger_type,60)||'lead_created',triggerConfig:input.triggerConfig||input.trigger_config||{},allowReentry:bool(input.allowReentry??definition.settings.allowReentry),definition};const errors=validateFlow(flow);if(status==='active'&&errors.length){const e=new Error(`Complete the automation before activating it: ${errors.join(' ')}`);e.validationErrors=errors;throw e;}let id=Number(input.id||0);if(id){const old=await env.DB.prepare('SELECT * FROM email_automation_flows WHERE id=?').bind(id).first();if(!old)throw new Error('Email automation was not found.');const latest=await env.DB.prepare('SELECT COALESCE(MAX(version_no),0) n FROM email_automation_versions WHERE flow_id=?').bind(id).first();await env.DB.prepare('INSERT INTO email_automation_versions(flow_id,version_no,snapshot_json) VALUES(?,?,?)').bind(id,Number(latest?.n||0)+1,JSON.stringify(rowFlow(old))).run();await env.DB.prepare(`UPDATE email_automation_flows SET name=?,category=?,status=?,trigger_type=?,trigger_config_json=?,allow_reentry=?,definition_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(flow.name,flow.category,flow.status,flow.triggerType,JSON.stringify(flow.triggerConfig),flow.allowReentry?1:0,JSON.stringify(definition),id).run();}else{const r=await env.DB.prepare(`INSERT INTO email_automation_flows(name,category,status,trigger_type,trigger_config_json,allow_reentry,definition_json) VALUES(?,?,?,?,?,?,?)`).bind(flow.name,flow.category,flow.status,flow.triggerType,JSON.stringify(flow.triggerConfig),flow.allowReentry?1:0,JSON.stringify(definition)).run();id=Number(r?.meta?.last_row_id||0);}if(status==='active'&&['lead_created','lead_updated'].includes(flow.triggerType))await enrollEmailAutomationForEvent(env,{eventType:flow.triggerType,flowId:id,limit:100});return getEmailAutomation(env,id);}
export async function setEmailAutomationStatus(env,id,status){await ensureEmailAutomationSchema(env);status=['active','draft','paused'].includes(status)?status:'paused';let flow=null;if(status==='active'){flow=await getEmailAutomation(env,id);const errors=validateFlow(flow);if(errors.length){const e=new Error(errors.join(' '));e.validationErrors=errors;throw e;}}await env.DB.prepare('UPDATE email_automation_flows SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(status,Number(id)).run();if(status==='active'&&['lead_created','lead_updated'].includes(flow?.trigger_type))await enrollEmailAutomationForEvent(env,{eventType:flow.trigger_type,flowId:Number(id),limit:100});}
export async function deleteEmailAutomation(env,id){await ensureEmailAutomationSchema(env);const r=await env.DB.prepare('DELETE FROM email_automation_flows WHERE id=?').bind(Number(id)).run();return Number(r?.meta?.changes||0)>0;}
export async function restoreEmailAutomationVersion(env,flowId,versionId){await ensureEmailAutomationSchema(env);const row=await env.DB.prepare('SELECT snapshot_json FROM email_automation_versions WHERE id=? AND flow_id=?').bind(Number(versionId),Number(flowId)).first();if(!row)throw new Error('The selected version was not found.');const snapshot=parse(row.snapshot_json,{});return saveEmailAutomation(env,{...snapshot,id:Number(flowId),status:'draft'});}

function fieldValue(lead,field){const map={client_name:'name',name:'name',first_name:'name',email:'email',phone:'phone',date_of_birth:'date_of_birth',age:'age',gender:'gender',location:'location',source:'source',status:'status',has_purchase:'has_purchase'};let v=lead[map[field]||field];if(field==='first_name')v=clean(v,160).split(/\s+/)[0]||'';return v??'';}
function matchRuleValue(actual,r){const a=String(actual??'').toLowerCase(),b=String(r.value||'').toLowerCase();switch(r.operator){case'is_true':return ['1','true','yes','attended','submitted','opened'].includes(a);case'is_false':return !['1','true','yes','attended','submitted','opened'].includes(a);case'is_empty':return!a;case'is_not_empty':return!!a;case'not_equals':return a!==b;case'contains':return a.includes(b);case'not_contains':return!a.includes(b);case'starts_with':return a.startsWith(b);case'greater_than':return Number(a)>Number(b);case'less_than':return Number(a)<Number(b);default:return a===b;}}
function contextWebinarId(context={}){const direct=Number(context.webinarEventId||context.webinar_id||0);if(direct>0)return direct;const match=String(context.eventId||'').match(/^webinar-(\d+)/);return Number(match?.[1]||0);}
async function automationRuleValue(env,lead,r,context={}){
  if(r.field==='webinar_attended'){
    const eventId=contextWebinarId(context);if(!eventId)return false;
    const phone=clean(lead.phone,80).replace(/\D/g,'').slice(-10),email=clean(lead.email,240).toLowerCase();
    const row=await env.DB.prepare(`SELECT 1 ok FROM webinar_members m LEFT JOIN webinar_events w ON w.id=m.source_event_id WHERE m.source_event_id=? AND (m.lead_id=? OR (?<>'' AND lower(trim(m.customer_email))=?) OR (?<>'' AND substr(replace(replace(replace(replace(replace(COALESCE(m.customer_phone,''),'+',''),' ',''),'-',''),'(',''),')',''),-10)=?)) AND trim(COALESCE(m.last_attendance_at,''))<>'' AND (w.starts_at IS NULL OR date(m.last_attendance_at)>=date(w.starts_at)) LIMIT 1`).bind(eventId,Number(lead.lead_id||lead.id||0),email,email,phone,phone).first().catch(()=>null);
    return !!row?.ok;
  }
  if(r.field==='previous_email_opened'){
    const row=await env.DB.prepare(`SELECT open_count FROM email_automation_runs WHERE enrollment_id=? AND step_type='email' ORDER BY id DESC LIMIT 1`).bind(Number(lead.enrollment_id||0)).first().catch(()=>null);
    return Number(row?.open_count||0)>0;
  }
  if(r.field==='contact_form_submitted_after_previous_email'){
    const row=await env.DB.prepare(`SELECT 1 ok FROM lead_submissions s WHERE s.lead_id=? AND s.submission_type='contact' AND datetime(s.created_at)>COALESCE((SELECT datetime(MAX(r.created_at)) FROM email_automation_runs r WHERE r.enrollment_id=? AND r.step_type='email'),datetime('1970-01-01')) LIMIT 1`).bind(Number(lead.lead_id||lead.id||0),Number(lead.enrollment_id||0)).first().catch(()=>null);
    return !!row?.ok;
  }
  return fieldValue(lead,r.field);
}
async function conditionPass(env,lead,c={},context={}){const rows=c.rules||[];if(!rows.length)return true;const results=[];for(const r of rows)results.push(matchRuleValue(await automationRuleValue(env,lead,r,context),r));return c.match==='any'?results.some(Boolean):results.every(Boolean);}
function triggerMatches(flow,lead,eventType,context={}){if(flow.trigger_type!==eventType&&!(eventType==='lead_updated'&&flow.trigger_type==='lead_created'))return false;const c=parse(flow.trigger_config_json,{});if(c.source&&c.source!=='all'&&String(lead.source||'').toLowerCase()!==String(c.source).toLowerCase())return false;if(c.productId&&Number(context.productId||0)!==Number(c.productId))return false;if(c.groupId&&Number(context.groupId||0)!==Number(c.groupId))return false;return true;}
function entryKey(flow,eventType,context={}){if(Number(flow.allow_reentry||0))return clean(context.eventId||`${eventType}-${new Date().toISOString()}`,160);return'initial';}
export async function enrollEmailAutomationForEvent(env,{leadId=0,eventType='lead_created',context={},flowId=0,limit=30}={}){await ensureEmailAutomationSchema(env);let leads=[];if(leadId){const x=await env.DB.prepare('SELECT * FROM contact_leads WHERE id=?').bind(Number(leadId)).first();if(x)leads=[x];}else{leads=(await env.DB.prepare(`SELECT * FROM contact_leads WHERE trim(COALESCE(email,''))<>'' ORDER BY id DESC LIMIT ?`).bind(Math.max(1,Math.min(250,Number(limit||30)))).all()).results||[];}let sql="SELECT * FROM email_automation_flows WHERE status='active'";const binds=[];if(flowId){sql+=' AND id=?';binds.push(Number(flowId));}else{sql+=' AND trigger_type IN (?,?)';binds.push(clean(eventType,60),eventType==='lead_updated'?'lead_created':'__none__');}sql+=' ORDER BY id LIMIT 100';const flows=(await env.DB.prepare(sql).bind(...binds).all()).results||[];let enrolled=0;for(const row of flows){const flow=rowFlow(row);for(const lead of leads){if(!EMAIL_RE.test(clean(lead.email,240))||!triggerMatches(row,lead,eventType,context))continue;const suppressed=await env.DB.prepare('SELECT 1 ok FROM email_automation_suppressions WHERE email=?').bind(clean(lead.email,240).toLowerCase()).first();if(suppressed)continue;const key=entryKey(row,eventType,context),r=await env.DB.prepare(`INSERT OR IGNORE INTO email_automation_enrollments(flow_id,lead_id,entry_key,context_json,status,current_step_index,next_run_at,updated_at) VALUES(?,?,?,?,'active',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)`).bind(flow.id,lead.id,key,JSON.stringify(context||{})).run();enrolled+=Number(r?.meta?.changes||0);}}return {ok:true,enrolled};}

export async function triggerOrderEmailAutomation(env,orderId,eventType,extra={}){
  orderId=clean(orderId,160);if(!orderId)return {ok:true,skipped:true,reason:'No order ID.'};
  const order=await env.DB.prepare('SELECT * FROM orders WHERE order_id=?').bind(orderId).first().catch(()=>null);if(!order?.customer_email)return {ok:true,skipped:true,reason:'Order has no customer email.'};
  const lead=await env.DB.prepare("SELECT id FROM contact_leads WHERE lower(trim(COALESCE(email,'')))=? OR (?<>'' AND substr(replace(replace(replace(replace(replace(COALESCE(phone,''),'+',''),' ',''),'-',''),'(',''),')',''),-10)=?) ORDER BY CASE WHEN lower(trim(COALESCE(email,'')))=? THEN 0 ELSE 1 END,id DESC LIMIT 1").bind(clean(order.customer_email,240).toLowerCase(),clean(order.customer_phone,80).replace(/\D/g,'').slice(-10),clean(order.customer_phone,80).replace(/\D/g,'').slice(-10),clean(order.customer_email,240).toLowerCase()).first().catch(()=>null);if(!lead?.id)return {ok:true,skipped:true,reason:'No matching contact lead.'};
  const item=await env.DB.prepare("SELECT COALESCE(group_concat(product_name, ', '),'Membership') plan_name,COALESCE(SUM(unit_amount_paise*COALESCE(quantity,1)),0) amount_paise FROM order_items WHERE order_id=(SELECT id FROM orders WHERE order_id=?)").bind(orderId).first().catch(()=>({plan_name:'Membership',amount_paise:0})),base=String(env.PUBLIC_SITE_URL||env.SITE_URL||'https://dance-class-at2.pages.dev').replace(/\/$/,'');
  const context={eventId:`${eventType}-${orderId}-${clean(extra.reference||order.updated_at||Date.now(),100)}`,orderId,planName:item?.plan_name||'Membership',productName:item?.plan_name||'Membership',amount:`₹${(Number(extra.amountPaise||item?.amount_paise||order.amount_paise||0)/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`,failureReason:clean(extra.failureReason||order.failure_reason,500)||'the payment provider could not approve the payment',retryPaymentUrl:clean(extra.retryPaymentUrl,3000)||`${base}/my-orders`,renewalDate:clean(extra.renewalDate,120),cancellationDate:clean(extra.cancellationDate,120),...extra};
  const enrollment=await enrollEmailAutomationForEvent(env,{leadId:Number(lead.id),eventType,context}),processing=await processEmailAutomations(env,{leadId:Number(lead.id),limit:20});return {ok:true,enrollment,processing};
}

export async function enrollScheduledEmailAutomations(env){
  await ensureEmailAutomationSchema(env);
  const now=new Date(),today=now.toISOString().slice(0,10),birthdayTarget=new Date(now.getTime()+3*86400000).toISOString().slice(0,10);
  const flows=(await env.DB.prepare("SELECT * FROM email_automation_flows WHERE status='active' AND trigger_type IN ('birthday','exact_date') ORDER BY id LIMIT 50").all()).results||[];
  const signature=`${today}|${flows.map(x=>`${x.id}:${x.updated_at}`).join(',')}`,state=await env.DB.prepare("SELECT state_value FROM email_automation_state WHERE state_key='calendar_scan_signature'").first();
  if(state?.state_value===signature)return {ok:true,skipped:true,enrolled:0};
  let enrolled=0;
  for(const flow of flows){
    const config=parse(flow.trigger_config_json,{}),targetDate=flow.trigger_type==='birthday'?birthdayTarget:clean(config.date,10),monthDay=targetDate.slice(5);
    if(flow.trigger_type==='exact_date'&&clean(config.date,10)!==today)continue;
    const leads=flow.trigger_type==='birthday'
      ?(await env.DB.prepare("SELECT * FROM contact_leads WHERE trim(COALESCE(email,''))<>'' AND substr(date_of_birth,6,5)=? ORDER BY id LIMIT 500").bind(monthDay).all()).results||[]
      :(await env.DB.prepare("SELECT * FROM contact_leads WHERE trim(COALESCE(email,''))<>'' ORDER BY id DESC LIMIT 500").all()).results||[];
    for(const lead of leads){const key=`${flow.trigger_type}-${targetDate.slice(0,4)}`,r=await env.DB.prepare("INSERT OR IGNORE INTO email_automation_enrollments(flow_id,lead_id,entry_key,context_json,status,current_step_index,next_run_at,updated_at) VALUES(?,?,?,'{}','active',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").bind(flow.id,lead.id,key).run();enrolled+=Number(r?.meta?.changes||0);}
  }
  await env.DB.prepare("INSERT INTO email_automation_state(state_key,state_value,updated_at) VALUES('calendar_scan_signature',?,CURRENT_TIMESTAMP) ON CONFLICT(state_key) DO UPDATE SET state_value=excluded.state_value,updated_at=CURRENT_TIMESTAMP").bind(signature).run();
  return {ok:true,enrolled};
}

function minutesForDelay(c={},lead={},context={}){const amount=Math.max(0,Number(c.amount||0)),unit=c.unit||'days';if(unit==='minutes')return amount;if(unit==='hours')return amount*60;if(unit==='days')return amount*1440;if(unit==='weeks')return amount*10080;if(unit==='months')return amount*43200;const now=new Date(),next=new Date(now);if(unit==='event_time'){const factor=c.offsetUnit==='days'?1440:c.offsetUnit==='minutes'?1:60,reference=c.eventDirection==='before_start'?context.eventStartsAt||context.startsAt:context.eventEndsAt||context.endsAt||context.eventStartsAt||context.startsAt,target=new Date(reference||'');if(!Number.isNaN(target.getTime())){const offset=amount*factor*(c.eventDirection==='before_start'?-1:1);return Math.max(0,Math.round((target.getTime()+offset*60000-now.getTime())/60000));}return 0;}if(unit==='specific_time'){const [h,m]=String(c.atTime||'09:00').split(':').map(Number);next.setHours(h||0,m||0,0,0);if(next<=now)next.setDate(next.getDate()+1);}else if(unit==='day_of_week'){const map={sunday:0,monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6},target=map[c.weekday]??1,add=(target-now.getDay()+7)%7||7;next.setDate(now.getDate()+add);next.setHours(9,0,0,0);}else if(unit==='day_of_month'){next.setMonth(now.getMonth()+(now.getDate()>=Number(c.monthDay||1)?1:0),Number(c.monthDay||1));next.setHours(9,0,0,0);}else if(unit==='day_of_year'){next.setFullYear(now.getFullYear()+(now.getMonth()>Number(c.month||1)-1||(now.getMonth()===Number(c.month||1)-1&&now.getDate()>=Number(c.monthDay||1))?1:0),Number(c.month||1)-1,Number(c.monthDay||1));next.setHours(9,0,0,0);}else if(unit==='subscriber_field'){const d=new Date(fieldValue(lead,c.field));if(!Number.isNaN(d.getTime()))return Math.max(0,Math.round((d.getTime()-now.getTime())/60000));}return Math.max(0,Math.round((next.getTime()-now.getTime())/60000));}
function variableMap(lead={},ctx={}){const name=clean(lead.name,160),first=name.split(/\s+/)[0]||'';return {BrandName:ctx.brandName||'DropBeat Dance Studio',ClientName:name,Name:name,FirstName:first,Email:lead.email||'',Phone:lead.phone||'',DateOfBirth:lead.date_of_birth||'',Age:lead.age??'',Gender:lead.gender||'',Location:lead.location||'',Source:lead.source||'',WebsiteUrl:ctx.websiteUrl||'',ViewInBrowser:ctx.viewUrl||'',Unsubscribe:ctx.unsubscribeUrl||'',FlowName:ctx.flowName||'',StepName:ctx.stepName||'',ProductName:ctx.productName||ctx.planName||'your selected plan',PlanName:ctx.planName||ctx.productName||'your membership',Amount:ctx.amount||'',RenewalDate:ctx.renewalDate||'',FailureReason:ctx.failureReason||'the payment provider could not approve the payment',RetryPaymentUrl:ctx.retryPaymentUrl||ctx.checkoutUrl||ctx.websiteUrl||'',CancellationDate:ctx.cancellationDate||'',HoursLeft:ctx.hoursLeft||'24',CheckoutUrl:ctx.checkoutUrl||ctx.retryPaymentUrl||ctx.websiteUrl||'',EventTitle:ctx.eventTitle||'our event',EventUrl:ctx.eventUrl||ctx.websiteUrl||'',SurveyUrl:ctx.surveyUrl||ctx.websiteUrl||'',CourseName:ctx.courseName||'your course'};}
function vars(text,lead,ctx={}){const map=variableMap(lead,ctx);return String(text??'').replace(/@([A-Za-z][A-Za-z0-9_]*)|\{\{\s*([A-Za-z][A-Za-z0-9_]*)\s*\}\}/g,(m,a,b)=>map[a||b]??'').replace(/[ \t]+([,.!?])/g,'$1').replace(/\bHi\s*,/gi,'Hi,');}
function addUtm(url,c={}){if(!c.utmEnabled||!/^https?:\/\//i.test(url))return url;try{const u=new URL(url);u.searchParams.set('utm_source',c.utmSource||'email');u.searchParams.set('utm_medium',c.utmMedium||'automation');u.searchParams.set('utm_campaign',c.utmCampaign||'lead-follow-up');return u.toString();}catch{return url;}}
function renderBlock(b,lead,ctx,c){const text=vars(b.text,lead,ctx),url=addUtm(vars(b.url,lead,ctx),c),image=vars(b.imageUrl,lead,ctx);if(b.type==='heading')return `<h2 style="margin:20px 0 10px;color:${esc(c.design.headingColor)};font-size:26px;line-height:1.25">${esc(text)}</h2>`;if(b.type==='text')return `<p style="margin:0 0 14px;line-height:1.7;color:${esc(c.design.textColor)}">${esc(text).replace(/\n/g,'<br>')}</p>`;if(b.type==='button')return `<div style="text-align:center;margin:22px 0"><a href="${esc(url)}" style="display:inline-block;background:${esc(c.design.primaryColor)};color:#fff;text-decoration:none;padding:12px 22px;border-radius:${Number(c.design.buttonRadius||999)}px;font-weight:700">${esc(text||'Open')}</a></div>`;if(b.type==='image')return image?`<img src="${esc(image)}" alt="${esc(b.alt||text)}" style="display:block;width:100%;height:auto;border-radius:14px;margin:16px 0">`:'';if(b.type==='divider')return `<hr style="border:0;border-top:1px solid ${esc(c.design.borderColor)};margin:22px 0">`;if(b.type==='spacer')return '<div style="height:28px;line-height:28px">&nbsp;</div>';if(b.type==='navigation')return `<div style="text-align:center;margin:8px 0 20px">${(b.items||[]).map(x=>`<a href="${esc(addUtm(vars(x.url,lead,ctx),c))}" style="margin:0 9px;color:${esc(c.design.primaryColor)};text-decoration:none;font-weight:700">${esc(vars(x.text,lead,ctx))}</a>`).join('')}</div>`;if(b.type==='hero')return `<div style="padding:24px;border-radius:16px;background:${esc(c.design.secondaryColor)};margin:15px 0">${image?`<img src="${esc(image)}" alt="${esc(b.alt||'')}" style="width:100%;border-radius:12px;margin-bottom:14px">`:''}<h2 style="margin:0;color:${esc(c.design.headingColor)}">${esc(text)}</h2></div>`;if(b.type==='special')return `<div style="padding:18px;border-radius:16px;background:${esc(c.design.secondaryColor)};text-align:center;margin:18px 0">${(b.items||[]).map(x=>{const label=esc(vars(x.text,lead,ctx)),href=addUtm(vars(x.url,lead,ctx),c);return href?`<a href="${esc(href)}" style="display:block;color:${esc(c.design.headingColor)};font-weight:800;text-decoration:none;margin:5px 0">${label}</a>`:`<div style="color:${esc(c.design.headingColor)};font-weight:800;font-size:18px;margin:5px 0">${label}</div>`;}).join('')}</div>`;if(b.type==='columns'||b.type==='gallery'||b.type==='blog_rss'||b.type==='product'||b.type==='social')return `<table role="presentation" width="100%"><tr>${(b.items||[]).map(x=>{const label=esc(vars(x.text,lead,ctx)),href=addUtm(vars(x.url,lead,ctx),c),img=x.imageUrl?`<img src="${esc(vars(x.imageUrl,lead,ctx))}" alt="" style="width:100%;height:auto;border-radius:10px">`:'';return `<td style="padding:8px;vertical-align:top">${href?`<a href="${esc(href)}" style="color:${esc(c.design.primaryColor)};text-decoration:none">${img}${label?`<div style="margin-top:7px;font-weight:700">${label}</div>`:''}</a>`:`${img}${label?`<div style="margin-top:7px">${label}</div>`:''}`}</td>`;}).join('')}</tr></table>`;if(b.type==='footer')return `<p style="margin:22px 0 0;font-size:12px;line-height:1.6;color:#806b73">${esc(text)} ${ctx.unsubscribeUrl?`<a href="${esc(ctx.unsubscribeUrl)}" style="color:${esc(c.design.primaryColor)}">Unsubscribe</a>`:''}</p>`;return'';}
export async function renderEmailAutomation(env,step,lead={},ctx={}){const site=await getSiteSettings(env).catch(()=>({})),home=brandHomeUrl(env),logo=brandAssetUrl(env,site.logoUrl),brand=site.siteName||'DropBeat Dance Studio',c={...step.config,design:{...defaultDesign(),...(step.config?.design||{})}};c.design.primaryColor=c.design.primaryColor||site.primaryColor||'#4B55BE';c.design.secondaryColor=c.design.secondaryColor||site.accentColor||'#A469A8';ctx={...ctx,brandName:brand,websiteUrl:home};const body=(c.blocks||[]).map(b=>renderBlock(b,lead,ctx,c)).join(''),subject=vars(c.subject||'A message from @BrandName',lead,ctx),preheader=vars(c.preheader,lead,ctx),plainText=vars(c.plainText||'',lead,ctx);const html=`<!doctype html><html><body style="margin:0;padding:0;background:${esc(c.design.backgroundColor)};font-family:${esc(c.design.fontFamily)};color:${esc(c.design.textColor)}" data-uc-email-automation="1"><div style="display:none;max-height:0;overflow:hidden;color:transparent">${esc(preheader)}</div><table role="presentation" width="100%"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="640" style="width:100%;max-width:640px;background:${esc(c.design.contentBackground)};border:1px solid ${esc(c.design.borderColor)};border-radius:20px;overflow:hidden"><tr><td style="height:8px;background:${esc(c.design.primaryColor)}"></td></tr><tr><td style="padding:24px 30px 16px"><table role="presentation"><tr><td><img src="${esc(logo)}" alt="${esc(brand)}" width="62" height="62" style="object-fit:contain"></td><td style="padding-left:12px;font-size:23px;font-weight:800;color:${esc(c.design.primaryColor)}">${esc(brand)}</td></tr></table></td></tr><tr><td style="padding:0 30px 28px">${body}${c.trackOpens&&ctx.openUrl?`<img src="${esc(ctx.openUrl)}" width="1" height="1" alt="" style="display:block;width:1px;height:1px;overflow:hidden">`:''}</td></tr><tr><td style="padding:18px 30px;background:#fff5e7;border-top:1px solid ${esc(c.design.borderColor)};text-align:center;font-size:12px;color:#806b73">© ${new Date().getFullYear()} ${esc(brand)}. All rights reserved.<br>Website designed by <a href="https://instautomate.com" style="color:#1a73e8">Instautomate</a></td></tr></table></td></tr></table></body></html>`;return {subject,html,text:plainText||body.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim(),senderName:vars(c.senderName||brand,lead,ctx),replyTo:c.useDifferentReplyTo?vars(c.replyTo,lead,ctx):''};}

async function deliverEmail(env,flow,step,lead,enrollmentId,eventContext={}){const suppressed=await env.DB.prepare('SELECT 1 ok FROM email_automation_suppressions WHERE email=?').bind(clean(lead.email,240).toLowerCase()).first();if(suppressed)return {ok:false,skipped:true,reason:'Recipient unsubscribed.'};const token=crypto.randomUUID().replace(/-/g,''),base=String(env.PUBLIC_SITE_URL||env.SITE_URL||'https://dance-class-at2.pages.dev').replace(/\/$/,''),ctx={...eventContext,flowName:flow.name,stepName:step.name,openUrl:`${base}/api/email-automation/open?token=${encodeURIComponent(token)}`,unsubscribeUrl:`${base}/api/email-automation/unsubscribe?token=${encodeURIComponent(token)}`},rendered=await renderEmailAutomation(env,step,lead,ctx),out=await sendConfiguredEmail(env,{to:lead.email,subject:rendered.subject,html:rendered.html,text:rendered.text,fromName:rendered.senderName,replyTo:rendered.replyTo},{purpose:'email'});return {...out,token};}
async function internalNotification(env,flow,step,lead,eventContext={}){const social=await getSocialIntegrationSettings(env),providers=await getOutboundEmailSettings(env),gmail=social.gmail||{},primary=providers[providers.primaryProvider]||{},to=clean(step.config.email||primary.fromEmail||gmail.adminCopyEmail||gmail.connectedEmail,240);if(!EMAIL_RE.test(to))return {ok:false,skipped:true,reason:'No notification email is configured.'};const rendered=await renderEmailAutomation(env,{...emailStep('Internal notification',step.config.subject),config:{...emailStep().config,subject:step.config.subject,blocks:[{type:'heading',text:step.name},{type:'text',text:step.config.message}]}},lead,{...eventContext,flowName:flow.name,stepName:step.name});return sendConfiguredEmail(env,{to,subject:rendered.subject,html:rendered.html,text:rendered.text,fromName:rendered.senderName||'DropBeat Dance Studio'},{purpose:'email'});}
export async function processEmailAutomations(env,{limit=40,leadId=0}={}){
  await ensureEmailAutomationSchema(env);
  const safe=Math.max(1,Math.min(100,Number(limit||40))),budget=await reserveD1ReadBudget(env,{operation:leadId?'email-automation:event':'email-automation:scheduled',estimatedRows:40+safe*8,priority:leadId?'critical':'standard'});
  if(!budget.allowed)return {ok:true,skipped:true,processed:0,budget,reason:budget.reason};
  let sql=`SELECT e.id enrollment_id,e.current_step_index,e.flow_id,e.lead_id,e.context_json,f.name flow_name,f.category flow_category,f.status flow_status,f.trigger_type flow_trigger_type,f.trigger_config_json flow_trigger_config_json,f.allow_reentry flow_allow_reentry,f.definition_json flow_definition_json,l.* FROM email_automation_enrollments e JOIN email_automation_flows f ON f.id=e.flow_id JOIN contact_leads l ON l.id=e.lead_id WHERE e.status='active' AND f.status='active' AND datetime(e.next_run_at)<=datetime('now')`,bind=[];
  if(leadId){sql+=' AND e.lead_id=?';bind.push(Number(leadId));}
  sql+=' ORDER BY datetime(e.next_run_at),e.id LIMIT ?';bind.push(safe);
  const rows=(await env.DB.prepare(sql).bind(...bind).all()).results||[],results=[];
  for(const row of rows){
    const claim=await env.DB.prepare("UPDATE email_automation_enrollments SET status='processing',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='active'").bind(row.enrollment_id).run();
    if(Number(claim?.meta?.changes||0)!==1)continue;
    const flow={id:Number(row.flow_id),name:row.flow_name,category:row.flow_category,status:row.flow_status,trigger_type:row.flow_trigger_type,triggerConfig:parse(row.flow_trigger_config_json,{}),allowReentry:!!Number(row.flow_allow_reentry),definition:sanitizeDefinition(parse(row.flow_definition_json,{}))},steps=flow.definition.steps,i=Number(row.current_step_index||0),step=steps[i],eventContext=parse(row.context_json,{});
    try{
      if(!step){await env.DB.prepare("UPDATE email_automation_enrollments SET status='completed',completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(row.enrollment_id).run();continue;}
      let out={ok:true},advance=true,next=i+1,conditionResult=null;
      if(step.type==='delay'){
        const mins=minutesForDelay(step.config,row,eventContext);
        await env.DB.prepare("UPDATE email_automation_enrollments SET status='active',current_step_index=?,next_run_at=datetime('now',?),updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(i+1,`+${Math.max(0,Math.round(mins))} minutes`,row.enrollment_id).run();
        results.push({id:row.enrollment_id,status:'scheduled',minutes:mins});continue;
      }
      if(step.type==='condition'){
        conditionResult=await conditionPass(env,row,step.config,eventContext);
        const action=conditionResult?(step.config.trueAction||'continue'):(step.config.falseAction||'stop'),targetId=conditionResult?step.config.trueNextStepId:step.config.falseNextStepId;
        if(action==='stop')advance=false;
        else if(action==='jump'){
          const target=steps.findIndex((candidate,index)=>index>i&&candidate.id===targetId);
          if(target<0)throw new Error(`Condition “${step.name}” does not have a valid later destination step.`);
          next=target;
        }
      }else if(step.type==='email')out=await deliverEmail(env,flow,step,row,row.enrollment_id,eventContext);
      else if(step.type==='notification')out=await internalNotification(env,flow,step,row,eventContext);
      else if(step.type==='add_group'||step.type==='remove_group'){
        let gid=Number(step.config.groupId||0);
        if(!gid&&step.config.groupName){await env.DB.prepare('INSERT OR IGNORE INTO email_automation_groups(name) VALUES(?)').bind(step.config.groupName).run();gid=Number((await env.DB.prepare('SELECT id FROM email_automation_groups WHERE name=?').bind(step.config.groupName).first())?.id||0);}
        if(gid){if(step.type==='add_group'){await env.DB.prepare('INSERT OR IGNORE INTO email_automation_group_members(group_id,lead_id) VALUES(?,?)').bind(gid,row.lead_id).run();await enrollEmailAutomationForEvent(env,{leadId:Number(row.lead_id),eventType:'subscriber_group',context:{...eventContext,eventId:`group-${gid}-${row.enrollment_id}`,groupId:gid}});}else await env.DB.prepare('DELETE FROM email_automation_group_members WHERE group_id=? AND lead_id=?').bind(gid,row.lead_id).run();}
      }else if(step.type==='exit')advance=false;
      const status=step.type==='condition'?(conditionResult?'matched':'not_matched'):out.skipped?'skipped':out.ok?'sent':'failed';
      await env.DB.prepare(`INSERT INTO email_automation_runs(enrollment_id,flow_id,lead_id,step_id,step_type,status,provider_id,open_token,error_text) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(enrollment_id,step_id) DO UPDATE SET status=excluded.status,provider_id=excluded.provider_id,open_token=excluded.open_token,error_text=excluded.error_text,created_at=CURRENT_TIMESTAMP`).bind(row.enrollment_id,row.flow_id,row.lead_id,step.id,step.type,status,clean(out.id||'',400),clean(out.token||'',100),clean(out.reason||'',1000)).run();
      if(!out.ok&&!out.skipped)throw new Error(out.reason||'Email action failed.');
      if(!advance||next>=steps.length)await env.DB.prepare("UPDATE email_automation_enrollments SET status='completed',current_step_index=?,completed_at=CURRENT_TIMESTAMP,last_error='',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(next,row.enrollment_id).run();
      else await env.DB.prepare("UPDATE email_automation_enrollments SET status='active',current_step_index=?,next_run_at=CURRENT_TIMESTAMP,last_error='',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(next,row.enrollment_id).run();
      results.push({id:row.enrollment_id,status,step:step.type,nextStepIndex:next});
    }catch(e){
      await env.DB.prepare("UPDATE email_automation_enrollments SET status='active',next_run_at=datetime('now','+60 minutes'),last_error=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(clean(e.message,1000),row.enrollment_id).run();
      results.push({id:row.enrollment_id,status:'failed',error:e.message});
    }
  }
  return {ok:true,processed:results.length,results,budget};
}

export async function emailAutomationActivity(env,flowId=0){await ensureEmailAutomationSchema(env);let sql=`SELECT r.*,l.name lead_name,l.email lead_email,f.name flow_name FROM email_automation_runs r JOIN contact_leads l ON l.id=r.lead_id JOIN email_automation_flows f ON f.id=r.flow_id`,bind=[];if(flowId){sql+=' WHERE r.flow_id=?';bind=[Number(flowId)];}sql+=' ORDER BY r.id DESC LIMIT 200';return (await env.DB.prepare(sql).bind(...bind).all()).results||[];}
export async function trackEmailAutomationOpen(env,token){await ensureEmailAutomationSchema(env);await env.DB.prepare(`UPDATE email_automation_runs SET open_count=open_count+1,opened_at=CASE WHEN opened_at='' THEN CURRENT_TIMESTAMP ELSE opened_at END WHERE open_token=?`).bind(clean(token,100)).run();}
export async function unsubscribeEmailAutomation(env,token){await ensureEmailAutomationSchema(env);const row=await env.DB.prepare(`SELECT l.email FROM email_automation_runs r JOIN contact_leads l ON l.id=r.lead_id WHERE r.open_token=? ORDER BY r.id DESC LIMIT 1`).bind(clean(token,100)).first();if(!row?.email)return false;await env.DB.prepare(`INSERT OR REPLACE INTO email_automation_suppressions(email,reason,created_at) VALUES(?,'unsubscribed',CURRENT_TIMESTAMP)`).bind(clean(row.email,240).toLowerCase()).run();await env.DB.prepare(`UPDATE email_automation_enrollments SET status='unsubscribed',completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE lead_id IN (SELECT id FROM contact_leads WHERE lower(email)=?) AND status IN ('active','processing')`).bind(clean(row.email,240).toLowerCase()).run();return true;}
export async function sendEmailAutomationTest(env,{step,email}={}){await ensureEmailAutomationSchema(env);if(!EMAIL_RE.test(clean(email,240)))throw new Error('Enter a valid test email address.');const site=await getSiteSettings(env),base=String(env.PUBLIC_SITE_URL||env.SITE_URL||'https://dance-class-at2.pages.dev').replace(/\/$/,''),preview={name:'Zeenath Afreen',email,phone:'+91 98765 43210',location:'Hyderabad, TS, IN',date_of_birth:'1995-09-16',age:31,gender:'Not specified',source:'Email preview'},rendered=await renderEmailAutomation(env,sanitizeStep(step),preview,{flowName:'Email Preview',stepName:step?.name||'Test email',planName:'Premium Membership',amount:'₹1,250',renewalDate:'30 September 2026',failureReason:'The bank declined the payment',retryPaymentUrl:`${base}/my-orders`,checkoutUrl:`${base}/checkout`,hoursLeft:'24'});return sendConfiguredEmail(env,{to:email,subject:`[TEST] ${rendered.subject}`,html:rendered.html,text:rendered.text,fromName:site.siteName||'DropBeat Dance Studio',replyTo:rendered.replyTo},{purpose:'email'});}
